1	// contractlab —— 可热更新的本地接口场景服务
2	//
3	// 运行环境：Node.js 24（内置 TypeScript 类型擦除，可直接 `node app.ts`），
4	// 无任何外部运行依赖。
5	//
6	// 行为约定（详见 README.md）：
7	// - 业务接口由“方法 + 绝对路径”唯一标识，查询串不参与匹配，不支持路径模板；
8	// - 请求被完整接收后，才按当前配置匹配接口并同步“预留”响应序列的下一项，
9	//   序列耗尽后持续返回末项；预留之后客户端断开，仍计为一次消费；
10	// - POST /__contractlab/reload 重新读取同一配置文件：新配置全部有效时才
11	//   原子替换全部接口、重置全部序列并递增版本号；失败时现状不变；
12	// - 在途请求持有预留时的旧响应快照（状态码/响应头/正文/延迟/版本），
13	//   完成时不会推进新序列；
14	// - POST 接口可附加可选的 requestBody 正文结构规则：请求完整接收后先校验
15	//   媒体类型与 JSON 结构，不符时返回 400 差异报告，不发送场景响应、不消费序列；
16	//   校验通过才按“完整接收”顺序预留响应项。
17	// - 管理入口 GET /__contractlab/requests 查询本次进程内的请求记录（一致快照、
18	//   不推进序列），POST /__contractlab/requests/clear 清空记录；记录只存在内存中，
19	//   管理范围（/__contractlab 本身及 /__contractlab/ 前缀）的请求一律不记录。
20	// - compare 子命令：离线比较旧、新两份场景文件，判断沿用旧接口约定的客户端
21	//   是否仍能调用新版；报告写 stdout，不启动监听、不修改文件。
22	// - import 子命令：读取本地 OpenAPI 3.0 JSON 与现有场景配置，按“方法 + 字面
23	//   路径”选择文档操作，仅用操作 requestBody 转换出的正文规则替换各接口的
24	//   requestBody（保留接口顺序与 responses），新场景 JSON 写 stdout。
25	
26	import http from 'node:http';
27	import { readFile } from 'node:fs/promises';
28	import path from 'node:path';
29	
30	const APP_NAME = 'contractlab';
31	
32	// 管理入口（保留前缀，业务接口不得使用）
33	const ADMIN_PREFIX = '/__contractlab/';
34	const ADMIN_BASE = '/__contractlab';
35	const HEALTH_PATH = '/__contractlab/health';
36	const RELOAD_PATH = '/__contractlab/reload';
37	const REQUESTS_PATH = '/__contractlab/requests';
38	const REQUESTS_CLEAR_PATH = '/__contractlab/requests/clear';
39	
40	// 每个业务响应都携带当前配置版本
41	const VERSION_HEADER = 'X-Contractlab-Version';
42	
43	// 请求体上限（本机工具的防误操作保护，超出直接 413，不触碰任何序列）
44	const MAX_BODY_BYTES = 100 * 1024 * 1024;
45	
46	// 由服务器管理、业务配置不得覆盖的“传输头”（大小写不敏感）
47	const BLOCKED_HEADERS = new Set([
48	  'connection',
49	  'keep-alive',
50	  'content-length',
51	  'transfer-encoding',
52	]);
53	
54	// RFC 7230 token：合法的 HTTP 头名称字符
55	const HEADER_NAME_RE = /^[!#$%&'*+\-.^_`|~0-9A-Za-z]+$/;
56	
57	type HttpMethod = 'GET' | 'POST';
58	
59	// ---------------------------------------------------------------------------
60	// 请求正文结构规则（endpoints[].requestBody，仅 POST）
61	// ---------------------------------------------------------------------------
62	//
63	// 规则格式（JSON 对象，未知字段一律拒绝）：
64	//   { "type": "object", "fields": { "<名>": <字段规则>, ... }, "additionalProperties": false }
65	//   { "type": "array", "items": <规则> }
66	//   { "type": "string" | "number" | "integer" | "boolean" | "null" }
67	// 字段规则 = 任意规则 + 可选 "required": true（缺省为可缺省）；
68	// object 的 fields / additionalProperties 可省略（默认无字段声明、拒绝未声明字段）；
69	// array 必须声明 items。
70	
71	type ScalarKind = 'string' | 'number' | 'integer' | 'boolean' | 'null';
72	
73	type BodyRule =
74	  | {
75	      readonly kind: 'object';
76	      readonly fields: ReadonlyMap<string, FieldRule>;
77	      readonly additionalProperties: boolean;
78	    }
79	  | { readonly kind: 'array'; readonly items: BodyRule }
80	  | { readonly kind: ScalarKind };
81	
82	interface FieldRule {
83	  readonly rule: BodyRule;
84	  readonly required: boolean;
85	}
86	
87	interface ResponseSpec {
88	  readonly status: number;
89	  readonly headers: { readonly [name: string]: string };
90	  readonly body: string;
91	  readonly delay: number;
92	}
93	
94	interface EndpointSpec {
95	  readonly method: HttpMethod;
96	  readonly path: string;
97	  readonly responses: readonly ResponseSpec[];
98	  readonly bodyRule: BodyRule | undefined;
99	}
100	
101	interface LiveEndpoint {
102	  readonly key: string;
103	  readonly responses: readonly ResponseSpec[];
104	  readonly bodyRule: BodyRule | undefined;
105	  // 下一个待预留位置；到达末项后停在末项（持续复用）
106	  cursor: number;
107	}
108	
109	interface LiveState {
110	  readonly version: number;
111	  readonly endpoints: ReadonlyMap<string, LiveEndpoint>;
112	}
113	
114	interface ReloadResult {
115	  ok: boolean;
116	  version: number;
117	  error?: string;
118	}
119	
120	class ConfigError extends Error {
121	  constructor(message: string) {
122	    super(message);
123	    this.name = 'ConfigError';
124	  }
125	}
126	
127	// ---------------------------------------------------------------------------
128	// 配置校验
129	// ---------------------------------------------------------------------------
130	
131	function isPlainObject(value: unknown): value is Record<string, unknown> {
132	  return typeof value === 'object' && value !== null && !Array.isArray(value);
133	}
134	
135	function validatePath(p: string, where: string): void {
136	  if (p.length === 0 || p[0] !== '/') {
137	    throw new ConfigError(`${where}.path 必须是以 "/" 开头的绝对路径，收到 "${p}"`);
138	  }
139	  if (p.length > 4096) {
140	    throw new ConfigError(`${where}.path 过长（最多 4096 字符）`);
141	  }
142	  for (const ch of p) {
143	    const code = ch.charCodeAt(0);
144	    if (ch === '?' || ch === '#' || ch === '{' || ch === '}') {
145	      throw new ConfigError(
146	        `${where}.path "${p}" 含有非法字符 "${ch}"：查询串不参与匹配，且不支持路径模板`,
147	      );
148	    }
149	    if (code <= 0x1f || code === 0x7f || code === 0x20) {
150	      throw new ConfigError(`${where}.path "${p}" 不得包含空白或控制字符`);
151	    }
152	  }
153	}
154	
155	function validateResponse(raw: unknown, where: string): ResponseSpec {
156	  if (!isPlainObject(raw)) {
157	    throw new ConfigError(`${where} 必须是对象`);
158	  }
159	  for (const key of Object.keys(raw)) {
160	    if (key !== 'status' && key !== 'headers' && key !== 'body' && key !== 'delay') {
161	      throw new ConfigError(`${where} 含未知字段 "${key}"`);
162	    }
163	  }
164	
165	  const { status, headers, body, delay } = raw;
166	
167	  if (!Number.isInteger(status) || status < 200 || status > 599) {
168	    throw new ConfigError(`${where}.status 必须是 200 至 599 之间的整数，收到 ${JSON.stringify(status)}`);
169	  }
170	
171	  if (!isPlainObject(headers)) {
172	    throw new ConfigError(`${where}.headers 必须是字符串键值对象`);
173	  }
174	  // 无原型对象：名为 "__proto__" 的头也按自有字段保留，不被原型 setter 吞掉
175	  const cleanHeaders: { [name: string]: string } = Object.create(null);
176	  const seenNames = new Set<string>();
177	  for (const [name, value] of Object.entries(headers)) {
178	    const whereHeader = `${where}.headers["${name}"]`;
179	    if (!HEADER_NAME_RE.test(name)) {
180	      throw new ConfigError(`${whereHeader} 不是合法的 HTTP 响应头名称`);
181	    }
182	    const lower = name.toLowerCase();
183	    if (BLOCKED_HEADERS.has(lower)) {
184	      throw new ConfigError(`${whereHeader} 属于服务器管理的传输头，不允许在配置中设置`);
185	    }
186	    if (seenNames.has(lower)) {
187	      throw new ConfigError(`${whereHeader} 与同序列内另一个响应头仅大小写不同，视为重复`);
188	    }
189	    if (typeof value !== 'string') {
190	      throw new ConfigError(`${whereHeader} 的值必须是字符串`);
191	    }
192	    for (let i = 0; i < value.length; i += 1) {
193	      const code = value.charCodeAt(i);
194	      // 允许水平制表符(0x09)；拒绝换行及其余控制字符；
195	      // Node 的 HTTP 头值只支持 Latin-1（0x80-0xFF），更高码位发送时会抛错
196	      if ((code <= 0x1f && code !== 0x09) || code === 0x7f || code > 0xff) {
197	        throw new ConfigError(
198	          `${whereHeader} 的值不得包含换行或其他控制字符，且只能使用 Latin-1 字符`,
199	        );
200	      }
201	    }
202	    seenNames.add(lower);
203	    cleanHeaders[name] = value;
204	  }
205	
206	  if (typeof body !== 'string') {
207	    throw new ConfigError(`${where}.body 必须是文本字符串`);
208	  }
209	  if ((status === 204 || status === 304) && body !== '') {
210	    throw new ConfigError(`${where}.body 状态码为 ${status} 时正文必须为空字符串`);
211	  }
212	
213	  if (!Number.isInteger(delay) || delay < 0 || delay > 60000) {
214	    throw new ConfigError(`${where}.delay 必须是 0 至 60000 之间的整数毫秒数，收到 ${JSON.stringify(delay)}`);
215	  }
216	
217	  return { status, headers: cleanHeaders, body, delay };
218	}
219	
220	const SCALAR_KINDS: ReadonlySet<string> = new Set([
221	  'string',
222	  'number',
223	  'integer',
224	  'boolean',
225	  'null',
226	]);
227	
228	function validateBodyRule(raw: unknown, where: string): BodyRule {
229	  if (!isPlainObject(raw)) {
230	    throw new ConfigError(`${where} 必须是对象（含 "type" 字段）`);
231	  }
232	
233	  const type = raw.type;
234	  const allowed = new Set(['type']);
235	  if (type === 'object') {
236	    allowed.add('fields');
237	    allowed.add('additionalProperties');
238	  } else if (type === 'array') {
239	    allowed.add('items');
240	  } else if (!SCALAR_KINDS.has(type as string)) {
241	    throw new ConfigError(
242	      `${where}.type 必须是 "object" | "array" | "string" | "number" | "integer" | "boolean" | "null"，收到 ${JSON.stringify(type)}`,
243	    );
244	  }
245	  for (const key of Object.keys(raw)) {
246	    if (!allowed.has(key)) {
247	      throw new ConfigError(`${where} 含未知字段 "${key}"`);
248	    }
249	  }
250	
251	  if (type === 'object') {
252	    const fieldsRaw = raw.fields;
253	    const fields = new Map<string, FieldRule>();
254	    if (fieldsRaw !== undefined) {
255	      if (!isPlainObject(fieldsRaw)) {
256	        throw new ConfigError(`${where}.fields 必须是对象（字段名 → 字段规则）`);
257	      }
258	      for (const [name, fieldRaw] of Object.entries(fieldsRaw)) {
259	        fields.set(name, validateFieldRule(fieldRaw, `${where}.fields[${JSON.stringify(name)}]`));
260	      }
261	    }
262	    const additional = raw.additionalProperties;
263	    if (additional !== undefined && typeof additional !== 'boolean') {
264	      throw new ConfigError(`${where}.additionalProperties 必须是布尔值`);
265	    }
266	    // 未声明字段默认拒绝
267	    return { kind: 'object', fields, additionalProperties: additional === true };
268	  }
269	
270	  if (type === 'array') {
271	    if (raw.items === undefined) {
272	      throw new ConfigError(`${where}.items 数组规则必须声明元素规则`);
273	    }
274	    return { kind: 'array', items: validateBodyRule(raw.items, `${where}.items`) };
275	  }
276	
277	  return { kind: type as ScalarKind };
278	}
279	
280	// 字段规则 = 任意规则 + 可选 "required"（仅允许出现在 object 的 fields 条目中）
281	function validateFieldRule(raw: unknown, where: string): FieldRule {
282	  if (!isPlainObject(raw)) {
283	    throw new ConfigError(`${where} 必须是对象（含 "type" 字段）`);
284	  }
285	  let required = false;
286	  // 无原型对象：未知规则键 "__proto__" 必须作为自有字段保留下来，
287	  // 交由 validateBodyRule 拒绝；普通对象字面量会在复制时被原型 setter 吞掉
288	  const rest: Record<string, unknown> = Object.create(null);
289	  for (const [key, value] of Object.entries(raw)) {
290	    if (key === 'required') {
291	      if (typeof value !== 'boolean') {
292	        throw new ConfigError(`${where}.required 必须是布尔值`);
293	      }
294	      required = value;
295	    } else {
296	      rest[key] = value;
297	    }
298	  }
299	  return { rule: validateBodyRule(rest, where), required };
300	}
301	
302	function validateEndpoint(
303	  raw: unknown,
304	  index: number,
305	  seen: Set<string>,
306	): EndpointSpec {
307	  const where = `endpoints[${index}]`;
308	  if (!isPlainObject(raw)) {
309	    throw new ConfigError(`${where} 必须是对象`);
310	  }
311	  for (const key of Object.keys(raw)) {
312	    if (key !== 'method' && key !== 'path' && key !== 'responses' && key !== 'requestBody') {
313	      throw new ConfigError(`${where} 含未知字段 "${key}"`);
314	    }
315	  }
316	
317	  const { method, path: routePath, responses, requestBody } = raw;
318	
319	  if (method !== 'GET' && method !== 'POST') {
320	    throw new ConfigError(`${where}.method 必须是 "GET" 或 "POST"，收到 ${JSON.stringify(method)}`);
321	  }
322	
323	  if (typeof routePath !== 'string') {
324	    throw new ConfigError(`${where}.path 必须是字符串`);
325	  }
326	  validatePath(routePath, where);
327	  if (routePath === '/__contractlab' || routePath.startsWith(ADMIN_PREFIX)) {
328	    throw new ConfigError(
329	      `${where}.path "${routePath}" 与管理入口冲突：前缀 "${ADMIN_PREFIX}" 为管理接口保留`,
330	    );
331	  }
332	
333	  const key = `${method} ${routePath}`;
334	  if (seen.has(key)) {
335	    throw new ConfigError(`${where} 与其他接口重复（方法 + 路径必须唯一）：${key}`);
336	  }
337	  seen.add(key);
338	
339	  if (!Array.isArray(responses) || responses.length === 0) {
340	    throw new ConfigError(`${where}.responses 必须是非空数组`);
341	  }
342	  const cleanResponses = responses.map((item, j) =>
343	    validateResponse(item, `${where}.responses[${j}]`),
344	  );
345	
346	  let bodyRule: BodyRule | undefined;
347	  if (requestBody !== undefined) {
348	    if (method !== 'POST') {
349	      throw new ConfigError(`${where}.requestBody 仅允许在 POST 接口上声明（GET 接口不允许携带此规则）`);
350	    }
351	    bodyRule = validateBodyRule(requestBody, `${where}.requestBody`);
352	  }
353	
354	  return { method, path: routePath, responses: cleanResponses, bodyRule };
355	}
356	
357	function validateConfig(raw: unknown): EndpointSpec[] {
358	  if (!isPlainObject(raw)) {
359	    throw new ConfigError('配置顶层必须是 JSON 对象');
360	  }
361	  for (const key of Object.keys(raw)) {
362	    if (key !== 'endpoints') {
363	      throw new ConfigError(`未知顶层字段 "${key}"，仅允许 "endpoints"`);
364	    }
365	  }
366	  const list = raw.endpoints;
367	  if (!Array.isArray(list) || list.length === 0) {
368	    throw new ConfigError('endpoints 必须是至少包含一个接口的数组');
369	  }
370	  const seen = new Set<string>();
371	  return list.map((ep, i) => validateEndpoint(ep, i, seen));
372	}
373	
374	// ---------------------------------------------------------------------------
375	// 运行时状态：配置快照 + 每接口独立序列
376	// ---------------------------------------------------------------------------
377	
378	function buildState(version: number, specs: readonly EndpointSpec[]): LiveState {
379	  const endpoints = new Map<string, LiveEndpoint>();
380	  for (const spec of specs) {
381	    endpoints.set(`${spec.method} ${spec.path}`, {
382	      key: `${spec.method} ${spec.path}`,
383	      responses: spec.responses,
384	      bodyRule: spec.bodyRule,
385	      cursor: 0,
386	    });
387	  }
388	  return { version, endpoints };
389	}
390	
391	// 同步预留下一项；同一事件循环内按“完整接收”事件的先后串行调用，天然保序。
392	// 末项之后持续返回末项，不跳项、不复用未到位置的项。
393	// 返回本次消费位置（0 起）与该项；末项复用时位置停在 length-1。
394	function reserveNext(endpoint: LiveEndpoint): { position: number; item: ResponseSpec } {
395	  const last = endpoint.responses.length - 1;
396	  const position = endpoint.cursor < last ? endpoint.cursor : last;
397	  if (endpoint.cursor < last) {
398	    endpoint.cursor += 1;
399	  }
400	  return { position, item: endpoint.responses[position] };
401	}
402	
403	// ---------------------------------------------------------------------------
404	// 进程内请求记录
405	// ---------------------------------------------------------------------------
406	//
407	// 仅记录管理范围之外、完整接收且未超过正文上限的请求（场景响应、400、404）。
408	// 未收完整即断开或超出上限不创建记录、不消费序列。
409	// 编号按“完整接收”顺序在进程内单调递增，与接口消费位置是两回事；
410	// 清空与成功/失败重载都保留编号序列，编号不复用。记录只存在内存中，不写文件。
411	
412	// 写出生命周期（仅指服务器侧写出，不表示客户端已收到）：
413	//   pending     —— 已完整接收、计划响应待发送（延迟期间即可查到）
414	//   sent        —— 服务器已完成响应写出；此后连接正常关闭不再改变状态
415	//   interrupted —— 写出完成前连接断开或写入/发送失败
416	type DeliveryStatus = 'pending' | 'sent' | 'interrupted';
417	
418	// 计划响应：场景响应为 'scene'，400/404 等框架响应为 'framework'
419	interface PlannedResponseSnapshot {
420	  readonly kind: 'scene' | 'framework';
421	  readonly status: number;
422	  // 应用层响应头：配置头/框架头 + 服务器填写的准确版本头，不含传输层自动头
423	  readonly headers: { readonly [name: string]: string };
424	  // 配置/框架给出的响应正文文本（不含 HTTP 层按 Content-Length 等补出的字节）
425	  readonly body: string;
426	}
427	
428	interface RequestRecord {
429	  readonly id: number;
430	  readonly receivedAt: string;
431	  readonly request: {
432	    readonly method: string;
433	    // 含查询串的原始请求目标
434	    readonly target: string;
435	    readonly path: string;
436	    // 原始请求头：按在线顺序成对保留，名称大小写与重复头均不折叠
437	    readonly rawHeaders: readonly string[];
438	    readonly bodyBytes: number;
439	    // 正文原始字节的无损表示：合法 UTF-8 时以文本给出，否则以 base64 给出
440	    readonly body: { readonly encoding: 'utf-8' | 'base64'; readonly content: string };
441	  };
442	  // 完整接收那一刻选用的配置版本；在途请求的结论不随之后的 reload 改变
443	  configVersion: number;
444	  // matched=false：未匹配（404），不消费任何序列
445	  matched: boolean;
446	  endpoint: string | null;
447	  // null 表示未做正文校验（GET/未声明规则）；true=通过，false=拒绝并返回 400
448	  bodyValidationPassed: boolean | null;
449	  // 400 时实际返回的差异报告（与响应正文中的 JSON 同一份数据）
450	  bodyRejection: BodyReport | null;
451	  // 场景请求在序列中的消费位置（0 起）；400/404 没有消费位置，记为 null
452	  sequencePosition: number | null;
453	  sequenceLength: number | null;
454	  plannedResponse: PlannedResponseSnapshot | null;
455	  delivery: DeliveryStatus;
456	}
457	
458	// 已清空记录的投递回调落到空集合上：不取消响应，旧请求之后完成也不得重新出现。
459	class RequestLog {
460	  private records: RequestRecord[] = [];
461	  // 仍可能被投递事件更新的记录 id 集合（清空后旧 id 不在其中）
462	  private readonly live = new Map<number, RequestRecord>();
463	  private nextId = 1;
464	
465	  create(entry: {
466	    method: string;
467	    target: string;
468	    path: string;
469	    rawHeaders: readonly string[];
470	    body: Buffer;
471	    configVersion: number;
472	  }): RequestRecord {
473	    const id = this.nextId;
474	    this.nextId += 1;
475	    const record: RequestRecord = {
476	      id,
477	      receivedAt: new Date().toISOString(),
478	      request: {
479	        method: entry.method,
480	        target: entry.target,
481	        path: entry.path,
482	        rawHeaders: entry.rawHeaders,
483	        bodyBytes: entry.body.byteLength,
484	        body: encodeBodyLosslessly(entry.body),
485	      },
486	      configVersion: entry.configVersion,
487	      matched: false,
488	      endpoint: null,
489	      bodyValidationPassed: null,
490	      bodyRejection: null,
491	      sequencePosition: null,
492	      sequenceLength: null,
493	      plannedResponse: null,
494	      delivery: 'pending',
495	    };
496	    this.records.push(record);
497	    this.live.set(id, record);
498	    return record;
499	  }
500	
501	  // 写出完成；对已清空（不再存活）的记录是 no-op
502	  markDelivered(id: number, status: DeliveryStatus): void {
503	    const record = this.live.get(id);
504	    if (!record) {
505	      return;
506	    }
507	    // 一旦完成写出即为终态：之后的连接正常关闭不得回退为 interrupted
508	    if (record.delivery === 'sent') {
509	      return;
510	    }
511	    record.delivery = status;
512	  }
513	
514	  // 调用时一致快照：拷贝当前存活记录，不推进任何序列
515	  snapshot(): readonly RequestRecord[] {
516	    return [...this.records];
517	  }
518	
519	  // 清空一次移除当时全部记录（含待发送项）；不取消响应、不改配置/版本/序列。
520	  // 清空前已完整接收的请求随后完成或失败都不再出现。
521	  clear(): number {
522	    const removed = this.records.length;
523	    this.records = [];
524	    this.live.clear();
525	    return removed;
526	  }
527	}
