540	// ---------------------------------------------------------------------------
541	// 请求正文校验：媒体类型 → UTF-8 JSON 解析 → 结构比对
542	// ---------------------------------------------------------------------------
543	
544	interface StructureProblem {
545	  readonly pointer: string;
546	  readonly expected: string;
547	  readonly actual: string;
548	}
549	
550	interface BodyReport {
551	  readonly error: 'invalid_request_body';
552	  readonly stage: 'parse' | 'structure';
553	  readonly message: string;
554	  readonly problems: readonly StructureProblem[];
555	}
556	
557	function parseFailure(message: string): BodyReport {
558	  return { error: 'invalid_request_body', stage: 'parse', message, problems: [] };
559	}
560	
561	function jsonTypeOf(value: unknown): string {
562	  if (value === null) {
563	    return 'null';
564	  }
565	  if (Array.isArray(value)) {
566	    return 'array';
567	  }
568	  return typeof value;
569	}
570	
571	// RFC 6901 JSON Pointer 段转义：~ -> ~0，/ -> ~1
572	function escapePointerSegment(segment: string): string {
573	  return segment.replace(/~/g, '~0').replace(/\//g, '~1');
574	}
575	
576	// 结构比对：父节点类型不符时只报告该节点，不再深入制造子节点错误；
577	// 字段缺失（hasOwnProperty 为假）与合法的 JSON null 分开判断。
578	function checkRule(
579	  rule: BodyRule,
580	  value: unknown,
581	  pointer: string,
582	  problems: StructureProblem[],
583	): void {
584	  switch (rule.kind) {
585	    case 'string':
586	    case 'boolean':
587	      if (typeof value !== rule.kind) {
588	        problems.push({ pointer, expected: rule.kind, actual: jsonTypeOf(value) });
589	      }
590	      return;
591	    case 'null':
592	      if (value !== null) {
593	        problems.push({ pointer, expected: 'null', actual: jsonTypeOf(value) });
594	      }
595	      return;
596	    case 'number':
597	      if (typeof value !== 'number' || !Number.isFinite(value)) {
598	        problems.push({ pointer, expected: 'number', actual: jsonTypeOf(value) });
599	      }
600	      return;
601	    case 'integer':
602	      if (!Number.isInteger(value)) {
603	        problems.push({ pointer, expected: 'integer', actual: jsonTypeOf(value) });
604	      }
605	      return;
606	    case 'array': {
607	      if (!Array.isArray(value)) {
608	        problems.push({ pointer, expected: 'array', actual: jsonTypeOf(value) });
609	        return;
610	      }
611	      for (let i = 0; i < value.length; i += 1) {
612	        checkRule(rule.items, value[i], `${pointer}/${i}`, problems);
613	      }
614	      return;
615	    }
616	    case 'object': {
617	      if (!isPlainObject(value)) {
618	        problems.push({ pointer, expected: 'object', actual: jsonTypeOf(value) });
619	        return;
620	      }
621	      for (const [name, field] of rule.fields) {
622	        const childPointer = `${pointer}/${escapePointerSegment(name)}`;
623	        if (!Object.prototype.hasOwnProperty.call(value, name)) {
624	          if (field.required) {
625	            problems.push({
626	              pointer: childPointer,
627	              expected: `${field.rule.kind}（必填字段）`,
628	              actual: 'missing',
629	            });
630	          }
631	        } else {
632	          checkRule(field.rule, value[name], childPointer, problems);
633	        }
634	      }
635	      if (!rule.additionalProperties) {
636	        for (const key of Object.keys(value)) {
637	          if (!rule.fields.has(key)) {
638	            problems.push({
639	              pointer: `${pointer}/${escapePointerSegment(key)}`,
640	              expected: '未声明的字段（不允许）',
641	              actual: jsonTypeOf(value[key]),
642	            });
643	          }
644	        }
645	      }
646	      return;
647	    }
648	  }
649	}
