734	// ---------------------------------------------------------------------------
735	// 离线兼容报告（compare 子命令）
736	// ---------------------------------------------------------------------------
737	//
738	// 兼容方向固定为 旧 -> 新：旧配置能按“方法 + 字面路径”匹配且通过正文检查的
739	// 每一种请求，在新配置中仍须匹配并通过。只比较接口存在性与请求接受条件；
740	// 响应状态/头/正文/延迟与序列差异不影响结论。
741	//
742	// 双方都配置 requestBody 时，比较的是“规则所接受 JSON 值的集合包含关系”
743	// L(旧规则) ⊆ L(新规则)，而不是文本比较或抽样请求；每个不兼容点都附一份
744	// 具体反例（旧规则接受、新规则拒绝的完整 JSON 值）。
745	
746	interface ReportReason {
747	  // 正文差异：RFC 6901 指针（根为 ""）；接口级原因（如接口删除）无此字段
748	  readonly pointer?: string;
749	  readonly message: string;
750	}
751	
752	interface ReportExample {
753	  readonly method: HttpMethod;
754	  readonly path: string;
755	  readonly headers: { readonly [name: string]: string };
756	  readonly body: string;
757	}
758	
759	interface EndpointReport {
760	  readonly method: HttpMethod;
761	  readonly path: string;
762	  readonly compatible: boolean;
763	  readonly reasons: readonly ReportReason[];
764	  readonly example?: ReportExample;
765	}
766	
767	interface CompareReport {
768	  readonly compatible: boolean;
769	  readonly oldFile: string;
770	  readonly newFile: string;
771	  readonly endpoints: readonly EndpointReport[];
772	}
773	
774	interface BodyViolation {
775	  readonly pointer: string;
776	  readonly message: string;
777	  // 完整请求正文反例：被旧规则接受、被新规则拒绝
778	  readonly value: unknown;
779	}
780	
781	// 生成被规则接受的最小 JSON 值：object 只含必填字段，array 取空数组。
782	// 字段名可能是 "" 或 "__proto__"，一律用无原型对象按自有字段构造。
783	function sampleValue(rule: BodyRule): unknown {
784	  switch (rule.kind) {
785	    case 'string':
786	      return 'contractlab';
787	    case 'number':
788	    case 'integer':
789	      return 0;
790	    case 'boolean':
791	      return false;
792	    case 'null':
793	      return null;
794	    case 'array':
795	      return [];
796	    case 'object': {
797	      const obj: Record<string, unknown> = Object.create(null);
798	      for (const [name, field] of rule.fields) {
799	        if (field.required) {
800	          obj[name] = sampleValue(field.rule);
801	        }
802	      }
803	      return obj;
804	    }
805	  }
806	}
807	
808	// 在 object 规则的最小样本上补一个字段（字段值本身须被该字段规则接受）
809	function sampleObjectWith(
810	  rule: Extract<BodyRule, { kind: 'object' }>,
811	  name: string,
812	  value: unknown,
813	): Record<string, unknown> {
814	  const obj = sampleValue(rule) as Record<string, unknown>;
815	  obj[name] = value;
816	  return obj;
817	}
818	
819	// 生成被规则拒绝的 JSON 值（顶层类型即不符；任何规则都存在这样的值）
820	function violateValue(rule: BodyRule): unknown {
821	  switch (rule.kind) {
822	    case 'number':
823	      return 'contractlab'; // 非数字
824	    case 'integer':
825	      return 0.5; // 非整数
826	    default:
827	      return 0; // 非 string / boolean / null / object / array
828	  }
829	}
830	
831	function kindLabel(rule: BodyRule): string {
832	  if (rule.kind === 'object') {
833	    return rule.additionalProperties ? 'object（允许未声明字段）' : 'object（拒绝未声明字段）';
834	  }
835	  return rule.kind;
836	}
837	
838	// 选一个两个规则都未声明的字段名，用于构造“额外字段”反例
839	function freshFieldName(
840	  oldFields: ReadonlyMap<string, FieldRule>,
841	  newFields: ReadonlyMap<string, FieldRule>,
842	): string {
843	  for (let i = 0; ; i += 1) {
844	    const name = i === 0 ? 'extra' : `extra_${i}`;
845	    if (!oldFields.has(name) && !newFields.has(name)) {
846	      return name;
847	    }
848	  }
849	}
850	
851	// 递归判定 L(oldRule) ⊆ L(newRule)；把发现的每个反例（连同完整正文样本）推入 out。
852	// 不变式：value 必被 oldRule 接受、被 newRule 拒绝；pointer 用 RFC 6901 定位差异。
853	function collectViolations(
854	  oldRule: BodyRule,
855	  newRule: BodyRule,
856	  pointer: string,
857	  out: BodyViolation[],
858	): void {
859	  if (newRule.kind !== 'object' && newRule.kind !== 'array') {
860	    // 标量：仅同名兼容，外加 integer 放宽为 number；其余组合两集合相交为空或有差异
861	    const compatible =
862	      oldRule.kind === newRule.kind || (oldRule.kind === 'integer' && newRule.kind === 'number');
863	    if (!compatible) {
864	      // number -> integer 时样本必须是非整数，否则 0 会被新规则接受
865	      const value =
866	        oldRule.kind === 'number' && newRule.kind === 'integer' ? 0.5 : sampleValue(oldRule);
867	      out.push({
868	        pointer,
869	        value,
870	        message: `类型收紧：旧规则接受 ${kindLabel(oldRule)}，新规则只接受 ${newRule.kind}`,
871	      });
872	    }
873	    return;
874	  }
875	
876	  if (newRule.kind === 'array') {
877	    if (oldRule.kind !== 'array') {
878	      out.push({
879	        pointer,
880	        value: sampleValue(oldRule),
881	        message: `类型收紧：旧规则接受 ${kindLabel(oldRule)}，新规则只接受 array`,
882	      });
883	      return;
884	    }
885	    // 元素规则收紧：用非空数组 [反例] 体现（空数组双方都会接受）
886	    const sub: BodyViolation[] = [];
887	    collectViolations(oldRule.items, newRule.items, `${pointer}/0`, sub);
888	    for (const s of sub) {
889	      out.push({ pointer: s.pointer, message: s.message, value: [s.value] });
890	    }
891	    return;
892	  }
893	
894	  // newRule.kind === 'object'
895	  if (oldRule.kind !== 'object') {
896	    out.push({
897	      pointer,
898	      value: sampleValue(oldRule),
899	      message: `类型收紧：旧规则接受 ${kindLabel(oldRule)}，新规则只接受 object`,
900	    });
901	    return;
902	  }
903	
904	  // (a) 新规则的必填字段必须被旧规则保证存在（旧规则未声明或仅可选即存在反例）
905	  for (const [name, newField] of newRule.fields) {
906	    if (!newField.required) {
907	      continue;
908	    }
909	    const oldField = oldRule.fields.get(name);
910	    if (!oldField || !oldField.required) {
911	      out.push({
912	        pointer: `${pointer}/${escapePointerSegment(name)}`,
913	        // 旧规则的最小样本不含可缺省/未声明字段，恰为反例
914	        value: sampleValue(oldRule),
915	        message: `新规则要求必填字段 ${JSON.stringify(name)}，旧规则允许缺省该字段`,
916	      });
917	    }
918	  }
919	
920	  // (b) 旧规则声明的字段，在新规则下仍须被接受
921	  for (const [name, oldField] of oldRule.fields) {
922	    const childPointer = `${pointer}/${escapePointerSegment(name)}`;
923	    const newField = newRule.fields.get(name);
924	    if (!newField) {
925	      if (!newRule.additionalProperties) {
926	        out.push({
927	          pointer: childPointer,
928	          value: sampleObjectWith(oldRule, name, sampleValue(oldField.rule)),
929	          message: `新规则拒绝旧规则允许的字段 ${JSON.stringify(name)}（新规则未声明且 additionalProperties 为 false）`,
930	        });
931	      }
932	      continue;
933	    }
934	    const sub: BodyViolation[] = [];
935	    collectViolations(oldField.rule, newField.rule, childPointer, sub);
936	    for (const s of sub) {
937	      out.push({
938	        pointer: s.pointer,
939	        message: s.message,
940	        value: sampleObjectWith(oldRule, name, s.value),
941	      });
942	    }
943	  }
944	
945	  // (c) 旧规则允许未声明的额外字段时，新规则必须同样放行这些字段
946	  if (oldRule.additionalProperties) {
947	    if (!newRule.additionalProperties) {
948	      const name = freshFieldName(oldRule.fields, newRule.fields);
949	      out.push({
950	        pointer: `${pointer}/${escapePointerSegment(name)}`,
951	        value: sampleObjectWith(oldRule, name, 0),
952	        message: '旧规则允许未声明的额外字段，新规则拒绝（additionalProperties 为 false）',
953	      });
954	    } else {
955	      // 新规则虽放行额外字段，但其新声明的字段会约束旧版原本自由的取值
956	      for (const [name, newField] of newRule.fields) {
957	        if (oldRule.fields.has(name)) {
958	          continue;
959	        }
960	        out.push({
961	          pointer: `${pointer}/${escapePointerSegment(name)}`,
962	          value: sampleObjectWith(oldRule, name, violateValue(newField.rule)),
963	          message: `旧规则对额外字段 ${JSON.stringify(name)} 不限制取值，新规则要求其为 ${kindLabel(newField.rule)}`,
964	        });
965	      }
966	    }
967	  }
968	}
