1041	function compareConfigs(
1042	  oldSpecs: readonly EndpointSpec[],
1043	  newSpecs: readonly EndpointSpec[],
1044	  oldFile: string,
1045	  newFile: string,
1046	): CompareReport {
1047	  const newByKey = new Map<string, EndpointSpec>();
1048	  for (const spec of newSpecs) {
1049	    newByKey.set(`${spec.method} ${spec.path}`, spec);
1050	  }
1051	  const endpoints = oldSpecs.map((spec) =>
1052	    compareEndpoint(spec, newByKey.get(`${spec.method} ${spec.path}`)),
1053	  );
1054	  return {
1055	    compatible: endpoints.every((ep) => ep.compatible),
1056	    oldFile,
1057	    newFile,
1058	    endpoints,
1059	  };
1060	}
