1131	class ImportError extends Error {
1132	  constructor(message: string) {
1133	    super(message);
1134	    this.name = 'ImportError';
1135	  }
1136	}
1137	
1138	// allOf 交集的三态结论（整体语义，必须对“全部”分支一次判定，不能逐对折叠）：
1139	// - nonempty  交集非空，且现有规则种类可以精确表达，rule 即交集规则；
1140	// - empty     交集为空（连一个可接受的值都没有），reason 说明首个空点，
1141	//             loc 是首个贡献该空点分支的“对象级”位置（数组元素归到其所在对象）；
1142	// - inexpressible 交集非空，但现有规则种类表达不了，rule 是其“近似规则”
1143	//             （用于在外层把 inexpressible 精确收窄为 empty），loc 是首个贡献
1144	//             不可表达点分支的对象级位置，reason 说明不可表达的原因。
1145	//
1146	// 之所以不能在两两合并的中途拒绝：可选字段的“非空但不可表达”只是中间现象，
1147	// 再叠加一个封闭空对象分支后，真实交集可能恰好为空对象 {}（可表达）。
1148	type Intersection =
1149	  | { readonly tag: 'nonempty'; readonly rule: NormRule }
1150	  | { readonly tag: 'empty'; readonly reason: string; readonly loc: string }
1151	  | {
1152	      readonly tag: 'inexpressible';
1153	      readonly rule: NormRule;
1154	      readonly reason: string;
1155	      readonly loc: string;
1156	    };
1157	
1158	// 转换过程中的规范化规则：与 BodyRule 同构，但 object 的必填名集合单独保存，
1159	// 便于 allOf 交集计算；输出时再展开为场景规则 JSON。
1160	type NormRule =
1161	  | {
1162	      readonly kind: 'object';
1163	      readonly props: ReadonlyMap<string, NormRule>;
1164	      readonly required: ReadonlySet<string>;
1165	      readonly addl: boolean;
1166	    }
1167	  | { readonly kind: 'array'; readonly items: NormRule }
1168	  | { readonly kind: 'string' | 'number' | 'integer' | 'boolean' };
1169	
1170	type NormObject = Extract<NormRule, { kind: 'object' }>;
1171	
1172	interface ImportCtx {
1173	  // 整份 OpenAPI 文档（$ref 解析的根）
1174	  readonly doc: unknown;
1175	  readonly file: string;
1176	}
1177	
1178	function importErrorMessage(ctx: ImportCtx, where: string, message: string): string {
1179	  return where === ''
1180	    ? `OpenAPI 文件 ${ctx.file}：${message}`
1181	    : `OpenAPI 文件 ${ctx.file} 的 ${where}：${message}`;
1182	}
1183	
1184	function importFail(ctx: ImportCtx, where: string, message: string): never {
1185	  throw new ImportError(importErrorMessage(ctx, where, message));
1186	}
1187	
1188	const OPENAPI_ANNOTATION_KEYS: ReadonlySet<string> = new Set([
1189	  'title',
1190	  'description',
1191	  'example',
1192	  'nullable',
1193	]);
1194	
1195	const OPENAPI_SCALAR_TYPES: ReadonlySet<string> = new Set([
1196	  'string',
1197	  'number',
1198	  'integer',
1199	  'boolean',
1200	]);
1201	
1202	function hasOwnKey(value: object, key: string): boolean {
1203	  return Object.prototype.hasOwnProperty.call(value, key);
1204	}
