1206	// JSON Pointer 段反转义：~1 -> /，~0 -> ~；其余 “~” 用法非法
1207	function unescapeRefSegment(
1208	  segment: string,
1209	  ref: string,
1210	  ctx: ImportCtx,
1211	  where: string,
1212	): string {
1213	  let out = '';
1214	  for (let i = 0; i < segment.length; i += 1) {
1215	    const ch = segment[i];
1216	    if (ch === '~') {
1217	      const next = segment[i + 1];
1218	      if (next === '0') {
1219	        out += '~';
1220	        i += 1;
1221	      } else if (next === '1') {
1222	        out += '/';
1223	        i += 1;
1224	      } else {
1225	        importFail(ctx, where, `$ref "${ref}" 含非法的 "~" 转义（仅支持 ~0 与 ~1）`);
1226	      }
1227	    } else {
1228	      out += ch;
1229	    }
1230	  }
1231	  return out;
1232	}
