1290	// 解析一层或多层 $ref 并做节点级基础校验（必须是对象、nullable 仅可 false），
1291	// 返回落定的 schema 节点与其（含引用链的）位置。
1292	function resolveSchemaNode(
1293	  rawNode: unknown,
1294	  ctx: ImportCtx,
1295	  where: string,
1296	  refChain: readonly string[],
1297	): { n: Record<string, unknown>; nodeWhere: string; chain: readonly string[] } {
1298	  let node = rawNode;
1299	  let nodeWhere = where;
1300	  let chain = refChain;
1301	  // 引用节点可以层层指向另一个引用节点
1302	  for (;;) {
1303	    if (!isPlainObject(node)) {
1304	      importFail(ctx, nodeWhere, 'schema 必须是对象');
1305	    }
1306	    const ref = dereference(node, ctx, nodeWhere, chain);
1307	    if (!ref) {
1308	      break;
1309	    }
1310	    node = ref.target;
1311	    nodeWhere = ref.where;
1312	    chain = ref.refChain;
1313	  }
1314	  const n = node as Record<string, unknown>;
1315	  // nullable 仅允许 false（等同不声明，忽略）；true 属于非法值
1316	  if (hasOwnKey(n, 'nullable') && n.nullable !== false) {
1317	    importFail(ctx, `${nodeWhere}.nullable`, `仅支持 false（或不声明），收到 ${JSON.stringify(n.nullable)}`);
1318	  }
1319	  return { n, nodeWhere, chain };
1320	}
