1632	// 多个规则分支（标量/数组/对象）的交集，三态返回，结论与顺序、分组无关。
1633	function intersectRules(flat: readonly RuleBranch[], where: string): Intersection {
1634	  const first = flat[0].rule;
1635	  const isComposite = (k: NormRule['kind']): boolean => k === 'object' || k === 'array';
1636	
1637	  // 含对象/数组时，全部分支必须是同一种结构类型；对象/数组与标量、对象与数组
1638	  // 相交都为空。纯标量分支（如 number 与 integer）不在此拒绝，交给下方的
1639	  // 标量交集处理（number ∩ integer 取 integer，并非为空）。
1640	  if (isComposite(first.kind)) {
1641	    for (let i = 1; i < flat.length; i += 1) {
1642	      if (flat[i].rule.kind !== first.kind) {
1643	        return {
1644	          tag: 'empty',
1645	          reason: `类型 ${first.kind} 与 ${flat[i].rule.kind} 没有共同接受的值`,
1646	          loc: flat[i].loc,
1647	        };
1648	      }
1649	    }
1650	    if (first.kind === 'object') {
1651	      return intersectObjects(flat, where);
1652	    }
1653	
1654	    // first.kind === 'array'
1655	    // 数组只接受“每个元素都在元素交集内”的序列，空数组总被接受：
1656	    // - 元素交集可表达 -> 非空，items 取交集（空数组也接受）；
1657	    // - 元素交集为空 -> 真实交集仅含空数组，现有规则种类无法表达；
1658	    // - 元素交集非空但不可表达 -> 同样无法在不扩展规则种类的前提下表达。
1659	    const itemBranches: RuleBranch[] = flat.map((b) => ({
1660	      rule: (b.rule as Extract<NormRule, { kind: 'array' }>).items,
1661	      loc: `${b.loc}.items`,
1662	    }));
1663	    const itemRes = intersectRules(itemBranches, `${where}.items`);
1664	    if (itemRes.tag === 'empty') {
1665	      return {
1666	        tag: 'inexpressible',
1667	        rule: { kind: 'array', items: itemBranches[0].rule },
1668	        reason: `数组元素规则交集为空（${itemRes.reason}），交集仅含空数组，现有规则种类无法表达`,
1669	        loc: itemRes.loc,
1670	      };
1671	    }
1672	    if (itemRes.tag === 'inexpressible') {
1673	      return {
1674	        tag: 'inexpressible',
1675	        rule: { kind: 'array', items: itemRes.rule },
1676	        reason: `数组元素规则交集非空但无法表达：${itemRes.reason}`,
1677	        loc: itemRes.loc,
1678	      };
1679	    }
1680	    return { tag: 'nonempty', rule: { kind: 'array', items: itemRes.rule } };
1681	  }
1682	
1683	  // 全为标量（若混入对象/数组，首分支为标量而其后出现复合类型，交集为空）
1684	  for (let i = 1; i < flat.length; i += 1) {
1685	    if (isComposite(flat[i].rule.kind)) {
1686	      return {
1687	        tag: 'empty',
1688	        reason: `类型 ${first.kind} 与 ${flat[i].rule.kind} 没有共同接受的值`,
1689	        loc: flat[i].loc,
1690	      };
1691	    }
1692	  }
1693	
1694	  // 标量：顺序无关地求类型交集（number ∩ integer 取 integer）；遇空即整体为空
1695	  let acc: NormRule = first;
1696	  for (let i = 1; i < flat.length; i += 1) {
1697	    const hit = scalarIntersection(acc, flat[i].rule);
1698	    if (hit === null) {
1699	      return {
1700	        tag: 'empty',
1701	        reason: `类型 ${acc.kind} 与 ${flat[i].rule.kind} 没有共同接受的值`,
1702	        loc: flat[i].loc,
1703	      };
1704	    }
1705	    acc = hit;
1706	  }
1707	  return { tag: 'nonempty', rule: acc };
1708	}
1709	
1710	// 规范化规则 -> 场景规则 JSON（object 显式写出 fields 与 additionalProperties；
1711	// 字段名可能是 ""/"__proto__"/含斜杠波浪号，一律用无原型对象按自有字段构造）
1712	function normToRuleJson(rule: NormRule): Record<string, unknown> {
1713	  switch (rule.kind) {
1714	    case 'object': {
1715	      const fields: Record<string, unknown> = Object.create(null);
1716	      for (const [name, sub] of rule.props) {
1717	        const subJson = normToRuleJson(sub);
1718	        fields[name] = rule.required.has(name) ? { ...subJson, required: true } : subJson;
1719	      }
1720	      return { type: 'object', fields, additionalProperties: rule.addl };
1721	    }
1722	    case 'array':
1723	      return { type: 'array', items: normToRuleJson(rule.items) };
1724	    default:
1725	      return { type: rule.kind };
1726	  }
1727	}
