1729	// 转换一个操作的 requestBody；操作未声明 requestBody 时返回 undefined
1730	// （POST 移除接口旧规则；GET 本就不允许携带规则）。
1731	function importOperationBodyRule(
1732	  operation: Record<string, unknown>,
1733	  method: HttpMethod,
1734	  ctx: ImportCtx,
1735	  opWhere: string,
1736	): unknown {
1737	  if (!hasOwnKey(operation, 'requestBody')) {
1738	    return undefined;
1739	  }
1740	  const rbWhere = `${opWhere}.requestBody`;
1741	  if (method === 'GET') {
1742	    importFail(ctx, rbWhere, 'GET 操作不允许声明请求正文');
1743	  }
1744	  // requestBody 本身也可以是本文件内 $ref（可层层引用）
1745	  let node: unknown = operation.requestBody;
1746	  let nodeWhere = rbWhere;
1747	  let chain: readonly string[] = [];
1748	  for (;;) {
1749	    if (!isPlainObject(node)) {
1750	      importFail(ctx, nodeWhere, '必须是对象');
1751	    }
1752	    const ref = dereference(node, ctx, nodeWhere, chain);
1753	    if (!ref) {
1754	      break;
1755	    }
1756	    node = ref.target;
1757	    nodeWhere = ref.where;
1758	    chain = ref.refChain;
1759	  }
1760	  const rb = node as Record<string, unknown>;
1761	  for (const key of Object.keys(rb)) {
1762	    if (key !== 'required' && key !== 'content' && key !== 'description') {
1763	      importFail(ctx, nodeWhere, `含未支持的字段 "${key}"`);
1764	    }
1765	  }
1766	  if (rb.required !== true) {
1767	    importFail(
1768	      ctx,
1769	      `${nodeWhere}.required`,
1770	      `导入的请求正文约定一律按必填处理，required 必须为 true，收到 ${JSON.stringify(rb.required)}`,
1771	    );
1772	  }
1773	  const content = rb.content;
1774	  if (!isPlainObject(content)) {
1775	    importFail(ctx, `${nodeWhere}.content`, '必须是对象且仅含 "application/json" 一种媒体类型');
1776	  }
1777	  const mediaTypes = Object.keys(content as Record<string, unknown>);
1778	  if (mediaTypes.length !== 1 || mediaTypes[0] !== 'application/json') {
1779	    importFail(
1780	      ctx,
1781	      `${nodeWhere}.content`,
1782	      `仅允许且必须包含 "application/json" 一种媒体类型，收到 ${JSON.stringify(mediaTypes)}`,
1783	    );
1784	  }
1785	  const media = (content as Record<string, unknown>)['application/json'];
1786	  const mediaWhere = `${nodeWhere}.content["application/json"]`;
1787	  if (!isPlainObject(media)) {
1788	    importFail(ctx, mediaWhere, '必须是对象');
1789	  }
1790	  for (const key of Object.keys(media as Record<string, unknown>)) {
1791	    if (key !== 'schema' && key !== 'example' && key !== 'examples') {
1792	      importFail(ctx, mediaWhere, `含未支持的字段 "${key}"`);
1793	    }
1794	  }
1795	  if (!hasOwnKey(media as Record<string, unknown>, 'schema')) {
1796	    importFail(ctx, mediaWhere, '缺少 schema');
1797	  }
1798	  const norm = schemaToNorm(
1799	    (media as Record<string, unknown>).schema,
1800	    ctx,
1801	    `${mediaWhere}.schema`,
1802	    [],
1803	  );
1804	  return normToRuleJson(norm);
1805	}
