1807	// 为场景每个接口选择文档操作并转换；任一失败抛 ImportError，不产生部分输出。
1808	// 未被选中的操作与不可达定义不参与转换。
1809	function importEndpoints(sceneRaw: unknown, ctx: ImportCtx): unknown[] {
1810	  const doc = ctx.doc;
1811	  if (!isPlainObject(doc)) {
1812	    importFail(ctx, '', '顶层必须是 JSON 对象');
1813	  }
1814	  const version = (doc as Record<string, unknown>).openapi;
1815	  if (typeof version !== 'string' || !/^3\.0\.\d+/.test(version)) {
1816	    importFail(ctx, 'openapi', `仅支持 OpenAPI 3.0.x，收到 ${JSON.stringify(version)}`);
1817	  }
1818	  const paths = (doc as Record<string, unknown>).paths;
1819	  if (!isPlainObject(paths)) {
1820	    importFail(ctx, 'paths', '必须是对象（路径 -> 路径项）');
1821	  }
1822	  const endpoints = (sceneRaw as { endpoints: unknown[] }).endpoints;
1823	  return endpoints.map((epRaw, index) => {
1824	    const ep = epRaw as { method: HttpMethod; path: string; responses: unknown };
1825	    const label = `场景接口 endpoints[${index}]（${ep.method} ${ep.path}）`;
1826	    if (!hasOwnKey(paths, ep.path)) {
1827	      importFail(ctx, 'paths', `${label} 缺少对应操作：路径 ${JSON.stringify(ep.path)} 不存在`);
1828	    }
1829	    const pathItem = (paths as Record<string, unknown>)[ep.path];
1830	    const pathWhere = `paths[${JSON.stringify(ep.path)}]`;
1831	    if (!isPlainObject(pathItem)) {
1832	      importFail(ctx, pathWhere, '必须是对象');
1833	    }
1834	    const methodKey = ep.method.toLowerCase();
1835	    if (!hasOwnKey(pathItem, methodKey)) {
1836	      importFail(ctx, pathWhere, `${label} 缺少对应操作：${methodKey} 操作不存在`);
1837	    }
1838	    const operation = (pathItem as Record<string, unknown>)[methodKey];
1839	    const opWhere = `${pathWhere}.${methodKey}`;
1840	    if (!isPlainObject(operation)) {
1841	      importFail(ctx, opWhere, '必须是对象');
1842	    }
1843	    const rule = importOperationBodyRule(operation, ep.method, ctx, opWhere);
1844	    // 仅替换 requestBody：保留接口顺序与 responses 原文
1845	    const out: { method: string; path: string; requestBody?: unknown; responses: unknown } = {
1846	      method: ep.method,
1847	      path: ep.path,
1848	      responses: ep.responses,
1849	    };
1850	    if (rule !== undefined) {
1851	      out.requestBody = rule;
1852	    }
1853	    return out;
1854	  });
1855	}
