1945	function versionHeaders(
1946	  version: number,
1947	  extra?: { readonly [name: string]: string },
1948	): { [name: string]: string } {
1949	  // 无原型对象：配置中名为 "__proto__" 的响应头在合并时不丢失
1950	  const headers: { [name: string]: string } = Object.create(null);
1951	  headers[VERSION_HEADER] = String(version);
1952	  if (extra) {
1953	    for (const [name, value] of Object.entries(extra)) {
1954	      headers[name] = value;
1955	    }
1956	  }
1957	  return headers;
1958	}
