201	
202	export interface RuleJson {
203	  readonly type: string;
204	  readonly fields?: { readonly [name: string]: RuleJson & { readonly required?: boolean } };
205	  readonly additionalProperties?: boolean;
206	  readonly items?: RuleJson;
