228	    case 'object': {
229	      if (!isPlainJsonObject(value)) {
230	        return false;
231	      }
232	      const fields = rule.fields ?? {};
233	      for (const [name, fieldRule] of Object.entries(fields)) {
234	        const has = Object.prototype.hasOwnProperty.call(value, name);
235	        if (!has) {
