62	// 管理/普通请求：UTF-8 文本往返
63	function textRequest(
64	  port: number,
65	  method: string,
66	  path: string,
67	  body?: string,
68	  headers: Record<string, string> = {},
69	): Promise<{ status: number; headers: Record<string, string | string[]>; body: string }> {
70	  return new Promise((resolve, reject) => {
71	    const h: Record<string, string> = { ...headers };
72	    if (body !== undefined) {
73	      h['Content-Length'] = String(Buffer.byteLength(body));
74	    }
75	    const r = httpConnect(port, method, path, h, (res) => {
76	      let data = '';
77	      res.setEncoding('utf8');
78	      res.on('data', (d: string) => (data += d));
79	      res.on('end', () => resolve({ status: res.statusCode ?? 0, headers: res.headers, body: data }));
80	    });
81	    r.on('error', reject);
82	    if (body !== undefined) {
83	      r.write(body);
84	    }
85	    r.end();
86	  });
87	}
