89	function httpConnect(
90	  port: number,
91	  method: string,
92	  path: string,
93	  headers: Record<string, string>,
94	  cb: (res: http.IncomingMessage) => void,
95	): http.ClientRequest {
96	  return http.request({ host: '127.0.0.1', port, method, path, headers }, cb);
97	}
