151	// 原始套接字请求：用于重复头、非法 UTF-8、半途断开等 HTTP 客户端不便表达的场景
152	function rawWrite(port: number, raw: Buffer): Promise<net.Socket> {
153	  return new Promise((resolve, reject) => {
154	    const socket = net.connect(port, '127.0.0.1', () => {
155	      socket.write(raw);
156	      resolve(socket);
157	    });
158	    socket.on('error', reject);
159	  });
160	}
