162	async function rawRequest(port: number, raw: Buffer): Promise<{ status: number; socket: net.Socket; read: () => Promise<Buffer> }> {
163	  const socket = await rawWrite(port, raw);
164	  const readers: Buffer[] = [];
165	  let waitEnd: (() => void) | undefined;
166	  const onEnd = (): void => waitEnd?.();
167	  socket.on('data', (c) => readers.push(c));
168	  socket.on('end', onEnd);
169	  let peek: { status: number } | undefined;
170	  // 等待状态行到达
171	  for (let i = 0; i < 100 && !peek; i += 1) {
172	    if (readers.length > 0) {
173	      const head = Buffer.concat(readers).toString('latin1');
174	      const m = head.match(/^HTTP\/1\.\d (\d{3})/);
175	      if (m) {
176	        peek = { status: Number(m[1]) };
177	        break;
178	      }
179	    }
180	    await sleep(5);
181	  }
182	  assert.ok(peek, '应收到响应状态行');
183	  return {
184	    status: (peek as { status: number }).status,
185	    socket,
186	    read: async () =>
187	      new Promise<Buffer>((resolve) => {
188	        if (socket.destroyed || socket.readableEnded) {
189	          resolve(Buffer.concat(readers));
190	          return;
191	        }
192	        waitEnd = () => resolve(Buffer.concat(readers));
193	      }),
194	  };
195	}
