Validation function:

```ts
function validateSnapshot(raw: unknown): SnapshotRecord[] {
  if (!isPlainObject(raw)) fail('快照顶层必须是 JSON 对象');
  const { count, records } = raw;
  if (!Array.isArray(records)) fail('records 必须是数组');
  if (!Number.isInteger(count) || count < 0) fail('count 必须是非负整数');
  if (count !== records.length) fail(`计数不符：count 为 ${count}，records 实际 ${records.length} 条`);
  const seen = new Set<number>();
  return records.map((rec, i) => validateSnapshotRecord(rec, `records[${i}]`, seen));
}
```

Per record:
```ts
function validateSnapshotRecord(raw, where, seenIds): SnapshotRecord {
  if (!isPlainObject(raw)) fail(`${where} 必须是对象`);
  const id = raw.id;
  if (!Number.isInteger(id) || id < 1) fail(`${where}.id 必须是正整数`);
  if (seenIds.has(id)) fail(`${where}.id ${id} 重复`);
  seenIds.add(id);
  const req = raw.request;
  if (!isPlainObject(req)) fail(`${where}.request 必须是对象`);
  const { method, target, path: recPath, rawHeaders, bodyBytes, body } = req;
  if (typeof method !== 'string' || method === '') fail(`${where}.request.method 必须是字符串`);
  if (typeof target !== 'string') fail(...);
  if (typeof recPath !== 'string') fail(...);
  const derived = target.split('?')[0];
  if (derived !== recPath) fail(`${where}.request.path "${recPath}" 与 target "${target}" 去掉查询串后的路径 "${derived}" 不符`);
  if (!Array.isArray(rawHeaders) || rawHeaders.some(h => typeof h !== 'string')) fail('rawHeaders 必须是字符串数组');
  if (rawHeaders.length % 2 !== 0) fail('rawHeaders 必须成对（名称、值交替），当前长度为奇数');
  if (!Number.isInteger(bodyBytes) || bodyBytes < 0) fail('bodyBytes 必须是非负整数');
  if (!isPlainObject(body)) fail('body 必须是对象');
  const { encoding, content } = body;
  if (encoding !== 'utf-8' && encoding !== 'base64') fail(`body.encoding 必须是 "utf-8" 或 "base64"，收到 ...`);
  if (typeof content !== 'string') fail('body.content 必须是字符串');
  let bytes: Buffer;
  if (encoding === 'utf-8') {
    bytes = Buffer.from(content, 'utf8');
  } else {
    if (!BASE64_RE.test(content)) fail('body.content 不是合法的 base64');
    bytes = Buffer.from(content, 'base64');
  }
  if (bytes.byteLength !== bodyBytes) fail(`正文长度不符：bodyBytes 为 ${bodyBytes}，按 ${encoding} 还原为 ${bytes.byteLength} 字节（快照可能已丢失字节，不猜补）`);
  // first content-type
  let contentType: string | undefined;
  for (let i = 0; i + 1 < rawHeaders.length; i += 2) {
    if (rawHeaders[i].toLowerCase() === 'content-type') { contentType = rawHeaders[i+1]; break; }
  }
  return { id, method, path: derived, contentType, body: bytes };
}
```

