type VerifyOutcome =
  | { readonly outcome: 'unmatched' }
  | { readonly outcome: 'accepted'; readonly bodyCheck: 'not-required' | 'passed' }
  | { readonly outcome: 'rejected'; readonly rejection: BodyReport };

function verifyRecord(req: VerifiedRequest, endpoints: ReadonlyMap<string, EndpointSpec>): VerifyOutcome {
  const endpoint =
    req.method === 'GET' || req.method === 'POST'
      ? endpoints.get(`${req.method} ${req.path}`)
      : undefined;
  if (!endpoint) return { outcome: 'unmatched' };
  if (!endpoint.bodyRule) return { outcome: 'accepted', bodyCheck: 'not-required' };
  const rejection = validateRequestBody(req.contentType, req.body, endpoint.bodyRule);
  if (rejection) return { outcome: 'rejected', rejection };
  return { outcome: 'accepted', bodyCheck: 'passed' };
}
