// ---------------------------------------------------------------------------
// 离线批量请求校验（verify 子命令）
// ---------------------------------------------------------------------------
// ... (comment block as drafted)

// 从快照重建出来、供重新判定的一条请求
interface VerifiedRequest {
  readonly id: number;
  readonly method: string;
  readonly path: string;
  // 在线顺序第一个 Content-Type 头的值（名称不分大小写）；没有则为 undefined
  readonly contentType: string | undefined;
  readonly body: Buffer;
}

const BASE64_RE = /^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/;

function snapshotFail(message: string): never {
  throw new Error(message);
}

function validateSnapshotRecord(raw: unknown, where: string, seenIds: Set<number>): VerifiedRequest {
  if (!isPlainObject(raw)) {
    snapshotFail(`${where} 必须是对象`);
  }
  const id = raw.id;
  if (!Number.isInteger(id) || (id as number) < 1) {
    snapshotFail(`${where}.id 必须是正整数，收到 ${JSON.stringify(id)}`);
  }
  if (seenIds.has(id as number)) {
    snapshotFail(`${where}.id ${id} 与其他记录重复（编号必须唯一）`);
  }
  seenIds.add(id as number);

  const request = raw.request;
  if (!isPlainObject(request)) {
    snapshotFail(`${where}.request 必须是对象`);
  }
  const { method, target, path: recordedPath, rawHeaders, bodyBytes, body } = request;
  const whereReq = `${where}.request`;
  if (typeof method !== 'string' || method === '') {
    snapshotFail(`${whereReq}.method 必须是非空字符串，收到 ${JSON.stringify(method)}`);
  }
  if (typeof target !== 'string') {
    snapshotFail(`${whereReq}.target 必须是字符串，收到 ${JSON.stringify(target)}`);
  }
  if (typeof recordedPath !== 'string') {
    snapshotFail(`${whereReq}.path 必须是字符串，收到 ${JSON.stringify(recordedPath)}`);
  }
  const derivedPath = (target as string).split('?')[0];
  if (derivedPath !== recordedPath) {
    snapshotFail(
      `${whereReq}.path ${JSON.stringify(recordedPath)} 与 target ${JSON.stringify(target)} 去掉查询串后的路径 ${JSON.stringify(derivedPath)} 不符`,
    );
  }
  if (!Array.isArray(rawHeaders) || rawHeaders.some((h) => typeof h !== 'string')) {
    snapshotFail(`${whereReq}.rawHeaders 必须是字符串数组（名称、值成对交替）`);
  }
  if (rawHeaders.length % 2 !== 0) {
    snapshotFail(`${whereReq}.rawHeaders 长度必须成对（名称、值交替），当前为 ${rawHeaders.length}`);
  }
  if (!Number.isInteger(bodyBytes) || (bodyBytes as number) < 0) {
    snapshotFail(`${whereReq}.bodyBytes 必须是非负整数，收到 ${JSON.stringify(bodyBytes)}`);
  }
  if (!isPlainObject(body)) {
    snapshotFail(`${whereReq}.body 必须是对象（含 encoding 与 content）`);
  }
  const { encoding, content } = body;
  if (encoding !== 'utf-8' && encoding !== 'base64') {
    snapshotFail(`${whereReq}.body.encoding 必须是 "utf-8" 或 "base64"，收到 ${JSON.stringify(encoding)}`);
  }
  if (typeof content !== 'string') {
    snapshotFail(`${whereReq}.body.content 必须是字符串`);
  }
  let bytes: Buffer;
  if (encoding === 'utf-8') {
    bytes = Buffer.from(content as string, 'utf8');
  } else {
    if (!BASE64_RE.test(content as string)) {
      snapshotFail(`${whereReq}.body.content 不是合法的 base64`);
    }
    bytes = Buffer.from(content as string, 'base64');
  }
  if (bytes.byteLength !== bodyBytes) {
    snapshotFail(
      `${whereReq} 正文长度不符：bodyBytes 为 ${bodyBytes}，按 ${encoding} 还原为 ${bytes.byteLength} 字节（快照可能已丢失字节，不猜补）`,
    );
  }

  // 重复头采用在线顺序第一项（名称不分大小写）
  let contentType: string | undefined;
  const headers = rawHeaders as string[];
  for (let i = 0; i + 1 < headers.length; i += 2) {
    if (headers[i].toLowerCase() === 'content-type') {
      contentType = headers[i + 1];
      break;
    }
  }

  return { id: id as number, method: method as string, path: derivedPath, contentType, body: bytes };
}

function validateSnapshot(raw: unknown): VerifiedRequest[] {
  if (!isPlainObject(raw)) {
    snapshotFail('快照顶层必须是 JSON 对象（GET /__contractlab/requests 的完整响应）');
  }
  const { count, records } = raw;
  if (!Array.isArray(records)) {
    snapshotFail('records 必须是数组');
  }
  if (!Number.isInteger(count) || (count as number) < 0) {
    snapshotFail(`count 必须是非负整数，收到 ${JSON.stringify(count)}`);
  }
  if ((count as number) !== records.length) {
    snapshotFail(`计数不符：count 为 ${count}，records 实际包含 ${records.length} 条`);
  }
  const seenIds = new Set<number>();
  return records.map((rec, i) => validateSnapshotRecord(rec, `records[${i}]`, seenIds));
}
