```ts
interface RawReply { status: number; body: Buffer; }

function rawExchange(port: number, raw: Buffer, timeoutMs = 10_000): Promise<RawReply> {
  return new Promise((resolve, reject) => {
    const socket = net.connect(port, '127.0.0.1', () => socket.write(raw));
    const chunks: Buffer[] = [];
    const timer = setTimeout(() => { socket.destroy(); reject(new Error('rawExchange 超时')); }, timeoutMs);
    socket.on('data', (c) => chunks.push(c));
    socket.on('error', (e) => { clearTimeout(timer); reject(e); });
    socket.on('end', () => {
      clearTimeout(timer);
      const all = Buffer.concat(chunks);
      const head = all.toString('latin1');
      const m = head.match(/^HTTP\/1\.\d (\d{3})/);
      resolve({ status: m ? Number(m[1]) : 0, body: all });
    });
  });
}
```

